const tabs=[...document.querySelectorAll("[data-tab]")];const panels=[...document.querySelectorAll("[data-panel]")];function openTab(name,updateHash=true){tabs.forEach(tab=>{const active=tab.dataset.tab===name;tab.classList.toggle("active",active);tab.setAttribute("aria-selected",String(active));tab.tabIndex=active?0:-1});panels.forEach(panel=>{const active=panel.dataset.panel===name;panel.classList.toggle("active",active);panel.hidden=!active});if(updateHash){history.replaceState(null,"",`#${name}`)}}tabs.forEach((tab,index)=>{tab.addEventListener("click",()=>openTab(tab.dataset.tab));tab.addEventListener("keydown",event=>{if(!["ArrowLeft","ArrowRight","Home","End"].includes(event.key))return;event.preventDefault();let target=index;if(event.key==="ArrowRight")target=(index+1)%tabs.length;if(event.key==="ArrowLeft")target=(index-1+tabs.length)%tabs.length;if(event.key==="Home")target=0;if(event.key==="End")target=tabs.length-1;tabs[target].focus();openTab(tabs[target].dataset.tab)})});const requestedTab=location.hash.replace("#","");if(tabs.some(tab=>tab.dataset.tab===requestedTab)){openTab(requestedTab,false)}document.querySelectorAll("[data-carousel]").forEach(carousel=>{const slides=[...carousel.querySelectorAll("[data-slide]")];const thumbnails=[...carousel.querySelectorAll("[data-carousel-go]")];let current=0;function showSlide(index){if(!slides.length)return;current=(index+slides.length)%slides.length;slides.forEach((slide,slideIndex)=>slide.classList.toggle("active",slideIndex===current));thumbnails.forEach((thumbnail,thumbnailIndex)=>{thumbnail.classList.toggle("active",thumbnailIndex===current);thumbnail.setAttribute("aria-current",thumbnailIndex===current?"true":"false")})}carousel.querySelector("[data-carousel-prev]")?.addEventListener("click",()=>showSlide(current-1));carousel.querySelector("[data-carousel-next]")?.addEventListener("click",()=>showSlide(current+1));thumbnails.forEach(thumbnail=>thumbnail.addEventListener("click",()=>showSlide(Number(thumbnail.dataset.carouselGo))));carousel.addEventListener("keydown",event=>{if(event.key==="ArrowLeft")showSlide(current-1);if(event.key==="ArrowRight")showSlide(current+1)});showSlide(0)});document.querySelectorAll(".detail-icon img, .carousel-slide img, .carousel-thumbnail img").forEach(image=>{image.addEventListener("error",()=>{if(image.closest(".detail-icon")){image.closest(".detail-icon").innerHTML="<span>EK</span>";return}if(image.closest(".carousel-thumbnail")){image.closest(".carousel-thumbnail").classList.add("image-missing");image.remove();return}const slide=image.closest(".carousel-slide");if(slide){const placeholder=document.createElement("div");placeholder.className="screenshot-missing";placeholder.innerHTML="<strong>Screenshot unavailable</strong>";image.replaceWith(placeholder)}},{once:true})});